mapper.select:
SELECT B1.* FROM ( SELECT A1.* -- , ROW_NUMBER() OVER(ORDER BY A1.insertDt DESC) AS PAGEINDEX , ROW_NUMBER() OVER( ORDER BY
A1.insertDt DESC
CASE WHEN A1.${sortColumn} ~ '^\d+$' THEN CAST(A1.${sortColumn} AS INTEGER) ELSE NULL END ${order}, A1.${sortColumn} ${order}
A1.${sortColumn} ${order}
) AS PAGEINDEX FROM ( SELECT CASE WHEN info.DISTRIBUTION_TYPE = 'FunctionCode' THEN 'Documents' WHEN info.DISTRIBUTION_TYPE = 'CCB' THEN '기술자료관리' ELSE info.DISTRIBUTION_TYPE END AS distributionType, info.DRAWING_NO AS drawingNo,
info.OBJECT_ID AS objectId, info.ORG_FILE_NM AS orgFileNm,
info.REVISION AS revision, info.USER_ID AS userId, info.INSERT_DATE AS insertDt, info.USER_NM AS userNm, info.LOG_TYPE AS logType, '' AS checkSum FROM DOCS_HISTORY info WHERE 1=1
AND info.DRAWING_NO = UPPER(TRIM(#{drawingNo}))
AND info.DRAWING_NO LIKE '%' || UPPER(TRIM(#{drawingNo})) || '%'
AND info.DISTRIBUTION_TYPE = 'CCB'
AND info.DISTRIBUTION_TYPE LIKE '%' || #{distributionType} || '%'
AND info.ORG_FILE_NM LIKE '%' || #{orgFileNm} || '%'
AND info.REVISION LIKE '%' || #{revision} || '%'
AND info.USER_ID = #{userId}
AND info.INSERT_DATE = #{insertDt}
AND info.USER_NM LIKE '%' || TRIM(#{userNm}) || '%'
AND info.LOG_TYPE = #{logType}
ORDER BY info.INSERT_DATE DESC
ORDER BY ${sortColumn} ${order}
) A1 ) B1 WHERE 1=1
AND PAGEINDEX <= #{end}
AND PAGEINDEX >= #{start}

SELECT COUNT(*) AS TOTAL_COUNT FROM ( SELECT A1.* FROM ( SELECT CASE WHEN info.DISTRIBUTION_TYPE = 'FunctionCode' THEN 'Documents' WHEN info.DISTRIBUTION_TYPE = 'CCB' THEN '기술자료관리' ELSE info.DISTRIBUTION_TYPE END AS distributionType,
info.OBJECT_ID AS objectId, info.ORG_FILE_NM AS orgFileNm, -- FN_GET_CD_NM('distributeTypeCd', info.DISTRIBUTE_TYPE_CD, 'ko') AS distributeTypeNm, info.REVISION AS revision, info.DRAWING_NO AS drawingNo, info.USER_ID AS userId, info.INSERT_DATE AS insertDt, info.USER_NM AS userNm, info.LOG_TYPE AS logType, '' AS checkSum FROM DOCS_HISTORY info WHERE 1=1
AND info.DISTRIBUTION_TYPE = 'CCB'
AND info.DISTRIBUTION_TYPE = #{distributionType}
AND info.OBJECT_ID LIKE '%' || #{objectId} || '%'
AND info.DRAWING_NO = UPPER(TRIM(#{drawingNo}))
AND info.DRAWING_NO LIKE '%' || UPPER(TRIM(#{drawingNo})) || '%'
AND info.ORG_FILE_NM LIKE '%' || #{orgFileNm} || '%'
AND info.REVISION = #{revision}
AND info.USER_ID = #{userId}
AND info.INSERT_DATE LIKE '%' || UPPER(TRIM(#{insertDt})) || '%'
AND info.USER_NM = #{userNm}
AND info.LOG_TYPE = #{logType}
) A1 ) B1
